from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Ankle":"Joint region connects lower leg and foot; several bones and ligaments allow flexing while supporting body weight.","Back":"Posterior trunk includes spine, muscles, ribs, skin, nerves, and connective tissues; posture and movement come from many structures working together.","Cheek":"Side of face contains skin, fat, muscles, and part of the cheekbone; cheek movement contributes to expression and chewing.","Digestive System":"Organ system breaks food into absorbable nutrients and moves waste onward; mouth, stomach, intestines, liver, pancreas and other organs contribute different steps.","Eye":"Sensory organ focuses light onto the retina; vision also depends on optic nerves and brain processing.","Finger":"Digit contains bones, joints, tendons, nerves, skin, and nails; fingers support touch and precise grip.","Grip":"Ability to hold/control objects comes from fingers, thumb, muscles, tendons, joints, sensation, and nervous-system control.","Hand":"Body part with palm, fingers and thumb supports touch, grasping, communication, and many fine movements.","Iris":"Colored muscular ring of the eye controls pupil size and therefore how much light enters.","Joint":"Connection between bones; different joint types allow movement, stability, or both.","Knuckle":"Prominent joint area where finger bones meet hand or each other; bending comes from the joint, tendons, and muscles.","Leg":"Lower limb region supports standing and movement; hip, thigh, knee, lower leg, ankle, and foot work as a chain.","Muscle":"Contractile tissue generates force and movement; muscles also support posture, breathing, circulation, and internal organ functions.","Nail":"Hard keratin plate protects the tips of fingers/toes and supports fine touch; nail health cannot diagnose the whole body by itself.","Organ":"Body structure made of tissues performing specialized functions; heart, lungs, liver, skin and others are examples.","Palm":"Front surface of hand contains skin creases, nerves, muscles/tendons and connective tissue; it supports grip and touch.","Quick Pulse":"Pulse is a rhythmic pressure wave caused by each heartbeat; a quicker rate can follow activity, emotion, fever, medicines or illness, so context matters.","Rib":"Curved bone helps form the rib cage, protecting chest organs and moving with breathing.","Shoulder":"Region links arm to trunk through several joints, muscles and tendons, giving a wide range of motion.","Tongue":"Muscular organ helps move food, taste, speak and swallow; taste receptors are distributed across the tongue rather than strict taste zones.","Upper Arm":"Region between shoulder and elbow contains humerus plus muscles, nerves and blood vessels.","Vision":"Ability to perceive visual information depends on eyes, optic pathways and brain processing; it is more than eye sharpness alone.","Wrist":"Joint region links forearm to hand through multiple small carpal bones, ligaments and tendons.","X-ray":"Medical imaging uses ionizing radiation to create internal images, especially useful for bones; trained professionals control dose and positioning.","Y-shaped Bone Model":"Project teaching model shaped like Y; it demonstrates a bone/model concept but is not proof that a normal human bone universally has this shape.","Zinc Bandage":"Project label for a zinc-containing dressing, such as zinc-oxide bandage used in some medical care; selection/application belongs to trained healthcare guidance.","Arm":"Upper limb from shoulder through hand in everyday use; bones, joints, muscles, nerves and vessels coordinate movement.","Belly":"Everyday word for abdomen, containing abdominal wall and many digestive/urinary/reproductive organs; outside shape does not reveal health by itself.","Elbow":"Joint between upper arm and forearm mainly bends/straightens and helps forearm rotation through nearby joints.","Foot":"Body structure with many bones, joints, muscles, tendons and sensory receptors; it supports weight, balance and walking.","Gum":"Gingiva is soft tissue around teeth that helps seal/protect tooth-supporting structures; healthy gums still need regular oral care.","Incisor":"Front cutting tooth with a relatively sharp edge; humans normally have incisors in upper and lower jaws.","Jaw":"Upper and lower jaw support teeth; the mandible is the movable lower jaw used in chewing and speech.","Knee":"Large joint connecting thigh and lower leg; bones, cartilage, menisci, ligaments, tendons and muscles share load and movement.","Lips":"Soft tissue around mouth opening supports speech, eating, expression and touch.","Mouth":"Opening and oral cavity begin digestion and support taste, chewing, swallowing, speech and breathing pathways.","Outer Ear":"Visible pinna plus outer ear canal collect/direct sound toward eardrum; hearing continues through middle/inner ear and brain.","Pupil":"Opening at center of iris lets light into eye; it appears black and changes size as iris muscles respond.","Retina":"Light-sensitive neural tissue lines back of eye and converts light into nerve signals sent toward brain.","Uvula":"Small soft-tissue projection hanging from soft palate; it contributes to swallowing/speech functions but is not the sole gag structure.","Voice":"Sound begins when airflow makes vocal folds vibrate, then throat, mouth and nose shape resonance and speech.","Xiphoid Bone":"Xiphoid process is the small lower part of sternum; it can be cartilaginous when young and ossifies variably with age.","Chin":"Lower front facial prominence formed mainly by mandible plus soft tissue; chin shape naturally varies.","Dimple":"Small skin indentation often linked to underlying facial structure/muscle variation; presence or absence is a normal trait.","Heart":"Muscular organ pumps blood through lungs and body; heart rate changes with activity, rest, emotion and health context.","Nose":"Structure supports smell and conditions inhaled air through nasal passages; smell receptors sit high in nasal cavity.","Quadriceps":"Group of four muscles at front of thigh primarily extends knee and helps control movement.","Toe":"Foot digit contributes to balance and push-off; big toe is especially important during walking.","Waist":"Everyday region between ribs and hips; waist size/shape varies and is not a moral or complete health measure.","Yawn":"Involuntary deep inhalation/open-mouth behavior associated with sleepiness, transitions in alertness and social contagion; exact biology is complex.","Zygomatic Bone":"Cheekbone forms part of cheek prominence and eye socket; one on each side connects with neighboring skull bones.","Skin":"Largest organ by surface area, providing barrier, sensation, temperature regulation and immune functions; appearance varies normally across people.",}
ACTIONS={"X-ray":"Point only; say medical imaging is professional equipment.","Zinc Bandage":"Point only; medical dressing application follows healthcare guidance.","Quick Pulse":"Tap two fingertips gently on opposite wrist without timing or diagnosing.","Y-shaped Bone Model":"Air-trace a Y; say it is a teaching model, not one universal bone shape.","Eye":"Point near your own eye without touching it.","Iris":"Point near eye picture, no touching.","Pupil":"Point to picture, no bright-light testing.","Retina":"Point to back-of-eye diagram, no self-test.","Uvula":"Point to diagram; do not touch throat.","Tongue":"Point to mouth picture; no touching/shared tools."}
